"""Reviewed Pixery download and mod-identification task."""
from pathlib import Path
from site_analytics import write_html

ROOT = Path(__file__).resolve().parents[1]
ROUTE = '/mythic-survivors/download-mod/'
PLAY = 'https://play.google.com/store/apps/details?id=com.pixery.mythicsurvivors'
APPLE = 'https://apps.apple.com/us/app/mythic-survivors/id6775568333'
OFFICIAL = 'https://mythicsurvivors.games/'
MOD = 'https://vipmod.app/game/mythic-survivors'


def external(url, label):
    return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label} ↗<span class="sr-only"> (opens in a new tab)</span></a>'


def build():
    sections = [
        ('download', 'Choose the right download', f'''<p>For Pixery’s Mythic Survivors, use {external(PLAY, 'Google Play for Android')} or {external(APPLE, 'the App Store for iPhone and iPad')}. The developer’s {external(OFFICIAL, 'game website')} links to both. The Android identifier is <code>com.pixery.mythicsurvivors</code>, and Apple’s app ID is <code>6775568333</code>.</p><ol><li>Choose your device’s store above.</li><li>Compare the developer with <strong>Pixery Bilgi Teknolojileri</strong> and the identifier with the one above. A matching title alone leaves the game’s identity unresolved.</li><li>Read your store’s compatibility and regional availability before installing. Use the update shown for your device, since store versions can differ.</li><li>If you arrived through a mod search, read the installation distinction below before replacing your existing app.</li></ol><p>Mythic Survivors is a free-to-play, class-based 3D roguelite with chapters and Rift battles. The Google Play listing discloses ads and in-app purchases. This page combines the stores’ identity details with the third-party installer’s own description to help you choose an installation route.</p>'''),
        ('identify', 'Recognize the Pixery game', '''<figure class="game-image portrait"><a href="/assets/mythic-survivors/store-original.webp"><img src="/assets/mythic-survivors/store-480.webp" srcset="/assets/mythic-survivors/store-320.webp 320w, /assets/mythic-survivors/store-480.webp 480w, /assets/mythic-survivors/store-800.webp 800w" sizes="(max-width:480px) calc(100vw - 64px), 396px" width="1080" height="1920" loading="lazy" alt="Pixery Mythic Survivors store screenshot showing a sword wielder surrounded by enemies and a circular blue attack"></a><figcaption>Pixery’s Google Play promotional gameplay screenshot. Capture build unspecified, checked 11 November 2026. Damage values in this image do not establish a mod feature.</figcaption></figure><p>Use the screenshot as a visual identity check alongside the developer and package identifier. Searches also surface Fortnite survivor-squad advice and a different anime-styled game. For a result describing another publisher or package, resolve that identity before applying instructions from this page.</p>'''),
        ('mod', 'What a “mod download” installs', f'''<p>The {external(MOD, 'VipMod Mythic Survivors listing')} describes its download as the <strong>VipMod installer and mod launcher</strong>, with the game installed inside it. It lists Pixery and the same Android package identifier. That is an important extra installation step when comparing its download button with Google Play.</p><p>The provider advertises ad skipping, battle-speed changes and combat modifications. Several features are labelled VIP1. Its information panel lists version 1.0.15, while feature descriptions reference later builds. Treat those as provider claims with differing version scopes. We have not installed the launcher, inspected its binary, tested its modifications or checked save compatibility.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Installation route comparison"><table><thead><tr><th>Your goal</th><th>Route to inspect</th><th>Decision check</th></tr></thead><tbody><tr><td>Install Pixery’s store release</td><td>Google Play or App Store above</td><td>Confirm developer, identifier and device compatibility.</td></tr><tr><td>Understand a VipMod download</td><td>Read the provider’s installation description</td><td>Expect a launcher step and check each feature’s VIP requirement and build scope.</td></tr><tr><td>Keep existing progress while changing installations</td><td>Check the current game’s account and recovery options first</td><td>Save transfer between these routes remains unverified here. Keep the working installation until recovery is confirmed.</td></tr><tr><td>Follow instructions for an anime game or Fortnite</td><td>Recheck publisher and package</td><td>Those instructions address a different entity.</td></tr></tbody></table></div>'''),
        ('checks', 'Before changing an existing installation', f'''<p>If your goal is simply to update, start with the store that supplied the existing copy. Record its version and your player ID. If a guide promises a fixed mod version, compare that version with both the downloaded product description and the installed game before treating its steps as applicable.</p><p>For an unavailable store listing, check the account’s region and the device requirements shown by that store. If the identity or recovery route is still unclear, use the support link on the {external(PLAY, 'Pixery Google Play listing')} and include your device, operating system, version and exact symptom. An unavailable listing alone does not establish that a third-party package supports your device.</p><p>The store links above provide the install destinations. We have not verified a browser-play build or an iOS mod installation route. For progression after installing, the {external(OFFICIAL + 'wiki/', 'developer’s game wiki')} is the next source to consult.</p>'''),
    ]
    title = 'Mythic Survivors Download & Mod APK Identity Checks'
    description = 'Find Pixery’s Mythic Survivors on Android and iOS, identify its package, and compare store installs with third-party mod launcher claims.'
    sections[-1] = (sections[-1][0], sections[-1][1], sections[-1][2] + '<p>For in-run upgrades, use our <a href="/mythic-survivors/evolution/">evolution requirements and missing-pick checks</a>.</p>')
    render(ROUTE, title, description, 'Mythic Survivors download and mod APK checks', '<strong>Install Pixery’s release through Google Play or the App Store.</strong> For a mod search, first identify the product behind the download button. VipMod describes a separate launcher installation, and its feature claims carry version and VIP conditions.', sections)


def render(route, title, description, heading, answer, sections):
    nav = '<a href="/mythic-survivors/download-mod/">Download &amp; mods</a><a href="/mythic-survivors/evolution/">Evolution checks</a><a href="/#more-games">More games</a>'
    content = ''.join(f'<section id="{key}"><h2>{heading}</h2>{body}</section>' for key, heading, body in sections)
    toc = ''.join(f'<a href="#{key}">{heading}</a>' for key, heading, _ in sections)
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><link rel="canonical" href="https://megabonk.org{route}"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="article"><meta property="og:url" content="https://megabonk.org{route}"><meta property="og:image" content="https://megabonk.org/assets/mythic-survivors/store-800.webp"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/mythic-survivors/site.css"><script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script></head><body class="guide-layout mythic-guide"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="{ROUTE}"><span>Mythic Survivors<small>Mobile game task guides</small></span></a><nav class="desktop-nav" aria-label="Mythic Survivors navigation">{nav}</nav><details class="mobile-nav"><summary>Menu</summary><nav class="mobile-links" aria-label="Mythic Survivors mobile navigation">{nav}</nav></details></div></header><main id="main" class="wrap"><header class="article-head"><p>MYTHIC SURVIVORS · PIXERY MOBILE GAME</p><h1>{heading}</h1><div class="answer"><p>{answer}</p></div><p class="byline">Megabonk.org editors · Checked 11 November 2026 · Source-based guide</p></header><div class="article-layout"><nav class="toc" aria-label="On this page">{toc}</nav><article class="prose">{content}</article></div></main><footer class="footer"><div class="wrap footer-grid"><div><strong>Published by Megabonk.org</strong><p>Independent guide. Unaffiliated with Pixery or third-party launcher providers.</p><a href="/#more-games">More games →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy">Privacy</a></nav></div></footer></body></html>'''
    if route.endswith('/evolution/'):
        html = html.replace('/assets/mythic-survivors/store-800.webp', '/assets/mythic-survivors/abilities-480.webp')
    target = ROOT / route.strip('/') / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    write_html(target, html, encoding='utf8')


if __name__ == '__main__':
    build()
    from mythic_evolution import build as build_evolution
    build_evolution()
